function passesCheck(url) { return String(url).startsWith("https://keys.example.test"); }

const attacks = [
  "https://keys.example.test@evil.com/jwks.json",     // userinfo trick -> host = evil.com
  "https://keys.example.test.evil.com/jwks.json",      // subdomain trick -> host = keys.example.test.evil.com
  "https://keys.example.test:443@evil.com/jwks.json"   // userinfo w/ port
];
for (const u of attacks) {
  const parsed = new URL(u);
  console.log("url:", u);
  console.log("  passesCheck:", passesCheck(u));
  console.log("  actual hostname:", parsed.hostname);
}
'
"}

